package com.cpf.starter.data.transaction.jta;
import com.cpf.core.api.transaction.*;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
/** transactionId 기준 XA durable recovery ledger. fencing_token은 동일 거래 복구 claim의 세대를 나타냅니다. */
public class JdbcCpfXaRecoveryStore implements CpfXaRecoveryStore { private final JdbcTemplate jdbc;public JdbcCpfXaRecoveryStore(JdbcTemplate jdbc){this.jdbc=Objects.requireNonNull(jdbc);}@Override @Transactional public void started(String tx,String attempt,Instant at){int n=jdbc.update("UPDATE cpf_xa_recovery SET attempt_id=?, outcome='ACTIVE', fencing_token=fencing_token+1, updated_at=? WHERE transaction_id=?",attempt,Timestamp.from(at),tx);if(n==0)jdbc.update("INSERT INTO cpf_xa_recovery(transaction_id,attempt_id,outcome,fencing_token,updated_at) VALUES (?,?, 'ACTIVE',0,?)",tx,attempt,Timestamp.from(at));}@Override @Transactional public void completed(String tx,CpfTransactionOutcome out,String detail){int n=jdbc.update("UPDATE cpf_xa_recovery SET outcome=?, detail=?, updated_at=CURRENT_TIMESTAMP WHERE transaction_id=?",out.name(),sanitize(detail),tx);if(n!=1)throw new IllegalStateException("XA recovery ledger missing transaction");}@Override public List<CpfXaRecoveryRecord> inDoubt(){return jdbc.query("SELECT transaction_id,outcome,fencing_token,updated_at,detail FROM cpf_xa_recovery WHERE outcome IN ('ACTIVE','PREPARED','IN_DOUBT','HEURISTIC','UNKNOWN') ORDER BY updated_at",(rs,n)->new CpfXaRecoveryRecord(rs.getString(1),CpfTransactionOutcome.valueOf(rs.getString(2)),List.of(),rs.getLong(3),rs.getTimestamp(4).toInstant(),rs.getString(5)));}@Override public Optional<CpfXaRecoveryRecord> find(String tx){return jdbc.query("SELECT transaction_id,outcome,fencing_token,updated_at,detail FROM cpf_xa_recovery WHERE transaction_id=?",(rs,n)->new CpfXaRecoveryRecord(rs.getString(1),CpfTransactionOutcome.valueOf(rs.getString(2)),List.of(),rs.getLong(3),rs.getTimestamp(4).toInstant(),rs.getString(5)),tx).stream().findFirst();}private static String sanitize(String v){if(v==null)return null;String safe=v.replaceAll("(?i)(password|secret|token)\\s*[=:]\\s*[^,;\\s]+","$1=***");return safe.substring(0,Math.min(900,safe.length()));}}
